def stage1_classify(model: str, comments: list[dict[str, Any]], workers: int = config.STAGE1_WORKERS) -> list[dict[str, Any]]:
    """Parallel map over batches + parallel repair pass for failed batches.

    TODO: ThreadPoolExecutor over classify_batch; collect failures; second
    ThreadPoolExecutor repair round; persist 10_classified.json.
    """
    import json
    import logging
    from pathlib import Path

    logger = logging.getLogger(__name__)
    batches = make_batches(comments)

    # First pass: parallel classification
    classified_results = [None] * len(comments)
    failed_batches = []

    with ThreadPoolExecutor(max_workers=workers) as executor:
        futures = {}
        for batch_idx, indices in enumerate(batches):
            future = executor.submit(classify_batch, model, comments, indices)
            futures[future] = (batch_idx, indices)

        for future in futures:
            batch_idx, indices = futures[future]
            try:
                classifications = future.result()
                for i, idx in enumerate(indices):
                    if i < len(classifications):
                        classified_results[idx] = classifications[i]
            except Exception as e:
                logger.warning(f"Batch {batch_idx} failed: {e}")
                failed_batches.append((batch_idx, indices))

    # Repair pass for failed batches
    if failed_batches:
        logger.info(f"Repairing {len(failed_batches)} failed batches")
        with ThreadPoolExecutor(max_workers=workers) as executor:
            futures = {}
            for batch_idx, indices in failed_batches:
                future = executor.submit(classify_batch, model, comments, indices)
                futures[future] = indices

            for future in futures:
                indices = futures[future]
                try:
                    classifications = future.result()
                    for i, idx in enumerate(indices):
                        if i < len(classifications):
                            classified_results[idx] = classifications[i]
                except Exception as e:
                    logger.error(f"Repair failed for batch: {e}")

