SYSTEM_S2 = """You are a YouTube niche researcher. From aggregated comment analysis
produce a research report as JSON with: videos_summary, discourse (topics, pains,
desires, questions, controversies, segments, emergent), opportunities (exactly 5).
Every verbatim quote MUST be copied exactly from the provided quotes. Write the report
in the query's language. Output JSON only."""


def verify_quotes(report: dict[str, Any], comments: list[dict[str, Any]]) -> list[str]:
    """Check every verbatim quote in the report exists in the source comments.

    Returns a list of problems (empty = pass). Unit-tested.
    """
    import re

    problems = []
    comment_texts = [c.get("text", "") for c in comments]

    # Find all quoted text in the report (in JSON we expect verbatim quotes)
    def extract_quotes(obj: Any) -> list[str]:
        quotes = []
        if isinstance(obj, dict):
            for v in obj.values():
                quotes.extend(extract_quotes(v))
        elif isinstance(obj, list):
            for item in obj:
                quotes.extend(extract_quotes(item))
        elif isinstance(obj, str):
            # Find quoted strings (simple heuristic: text in quotes or markdown code)
            # Look for quoted phrases that are likely verbatim
            match_quotes = re.findall(r'"([^"]{10,})"', obj)
            quotes.extend(match_quotes)
            match_backticks = re.findall(r'`([^`]{10,})`', obj)
            quotes.extend(match_backticks)
        return quotes

    quotes = extract_quotes(report)

    # Check each quote exists in source comments
    for quote in quotes:
        found = any(quote in comment_text for comment_text in comment_texts)
        if not found:
            problems.append(f"Quote not found in source comments: {quote[:50]}...")

    return problems


