            elif isinstance(discourse["segments"], list):
                for seg in discourse["segments"]:
                    if seg:
                        lines.append(f"- {seg}\n")

        if "emergent" in discourse:
            lines.append("### Emergent Patterns\n")
            if isinstance(discourse["emergent"], list):
                for pattern in discourse["emergent"]:
                    if pattern:
                        lines.append(f"- {pattern}\n")

    if "opportunities" in report:
        lines.append("## Market Opportunities\n")
        if isinstance(report["opportunities"], list):
            for i, opp in enumerate(report["opportunities"], 1):
                lines.append(f"{i}. {opp}\n")

    return "".join(lines)


